									::inet_ntop(AF_INET, &(reinterpret_cast <const struct sockaddr_in *> (&spc->spc_aaddr))->sin_addr, ::__awh_buffer__, INET_ADDRSTRLEN);
									// Выводим информацию о событии изменения адреса однорангового узла SCTP
